export function LandingPage() {
  const containerRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();
  const [earthMounted, setEarthMounted] = useState(false);

  useEffect(() => {
    setEarthMounted(true);
    const el = containerRef.current;
    if (!el) return;
    const clickHandler = (e: MouseEvent) => {
      const burger = (e.target as HTMLElement).closest(".lnav-hamburger");
      if (burger) {
        e.preventDefault();
        const nav = el.querySelector(".lnav");
        nav?.classList.toggle("menu-open");
        return;
      }
      const target = (e.target as HTMLElement).closest("a");
      if (!target) return;
      el.querySelector(".lnav")?.classList.remove("menu-open");
      const href = target.getAttribute("href");

      // 1. Sign In -> /login
      if (target.classList.contains("si") || target.innerText?.trim() === "Sign In" || target.innerText?.trim() === "Sign In"  || href === "/login") {
        e.preventDefault();
        navigate("/login");
        return;
      }
      // 2. Get Started -> /register
      if (target.classList.contains("gs") || target.innerText?.trim() === "Get Started" || target.innerText?.trim() === "Register"  || href === "/register") {
        e.preventDefault();
        navigate("/register");
        return;
      }
      // 3. "Launch Platform" button: require authentication
      if (target.classList.contains("wp") || target.classList.contains("wp-mobile") ) {
        e.preventDefault();
        if (isAuthenticated) {
          navigate("/dashboard");
        } else {
          navigate("/login?redirect=/dashboard");
        }
        return;
      }

      if (!href) return;
      if (href.startsWith("http://") || href.startsWith("https://")) {
        return;
      }
      if (href.startsWith("#")) {
        return;
      }
      if (href.startsWith("/")) {
        e.preventDefault();
        if (!isAuthenticated && href !== "/" && href !== "/login" && href !== "/register") {
          navigate(`/login?redirect=${encodeURIComponent(href)}`);
        } else {
          navigate(href);
        }
        return;
      }
      if (href.endsWith(".dc.html") || href.includes(".dc.")) {
        e.preventDefault();
        const route = "/" + href.replace(/\.dc\.html$/, "").toLowerCase();
        if (!isAuthenticated) {
          navigate(`/login?redirect=${encodeURIComponent(route)}`);
        } else {
          navigate(route);
        }
        return;
      }
    };
    el.addEventListener("click", clickHandler);
    return () => el.removeEventListener("click", clickHandler);
  }, [navigate, isAuthenticated]);

  const host = earthMounted ? document.getElementById("earth-3d-container") : null;

  return (
    <>
      <div
        ref={containerRef}
        dangerouslySetInnerHTML={{ __html: LANDING_MARKUP }}
      />
      {host && createPortal(<EarthCanvas />, host)}
    </>
  );
}
